        { label: L.retestFailed, accelerator: "CmdOrCtrl+Shift+R", click: () => callbacks.onMenuAction("retest-failed-keys") },
        { type: "separator" },
        { label: L.generateConfig, click: () => callbacks.onNavigate("/keys/working") }
